// A carried domain is DATA. What an app does with one is read its identifier, its display name and where
// it sits relative to the document storage, and hand it to the manager - and the manager is where this
// release's own behaviour would have to come from, which it has none of.
//
// THE IVARS ARE ON THIS CLASS. The first version of this file put them on a separate
// NSFileProviderDomainCharonStorage and had initWithIdentifier: return one of those, which is not an
// NSFileProviderDomain at all. The compiler said so -
//     incompatible pointer types returning 'NSFileProviderDomainCharonStorage *' from a function with
//     result type 'NSFileProviderDomain *'
// - and it was right: a caller holding that object back is holding the wrong class, and the port has to
// answer as a real NSFileProviderDomain. So the state lives here and the init fills it in.

// -initWithIdentifier:displayName: is declared by this class and answered by the 16.0 CATEGORY, because
// release-split refuses one object whose symbols first appear in two releases. That is the same reason as
// UIAction.m's pragma and the same reason it carries its reason on the line.
#pragma clang diagnostic ignored "-Wincomplete-implementation"
#pragma clang diagnostic ignored "-Wobjc-protocol-method-implementation"
@implementation NSFileProviderDomain {
  NSString *_charonIdentifier;
  NSString *_charonDisplayName;
  NSString *_charonRelative;
  NSUUID *_charonVolumeUUID;
  BOOL _charonUserEnabled;
  BOOL _charonIsReplicated;
  BOOL _charonHidden;
  BOOL _charonSupportsSyncingTrash;
}
@synthesize identifier = _charonIdentifier;
@synthesize displayName = _charonDisplayName;
@synthesize pathRelativeToDocumentStorage = _charonRelative;

@synthesize volumeUUID = _charonVolumeUUID;

// The four flags the 16.0 header carries, stored here and filled through the one method the category can
// reach, because a category has no ivar of its own on this target.
- (void)charon_setUserEnabled:(BOOL)userEnabled replicated:(BOOL)replicated
                     hidden:(BOOL)hidden supportsSyncingTrash:(BOOL)supportsSyncingTrash
{
  _charonUserEnabled = userEnabled;
  _charonIsReplicated = replicated;
  _charonHidden = hidden;
  _charonSupportsSyncingTrash = supportsSyncingTrash;
}
- (BOOL)charon_userEnabled { return _charonUserEnabled; }
- (BOOL)charon_replicated { return _charonIsReplicated; }
- (BOOL)charon_hidden { return _charonHidden; }
- (BOOL)charon_supportsSyncingTrash { return _charonSupportsSyncingTrash; }

// NOT BUILT IN THIS OBJECT, AND SAID SO RATHER THAN CLAIMED. -initWithIdentifier:displayName: and the
// members below are this class's own at 16.0 and later, or are API_UNAVAILABLE(ios) in the SDK's own header,
// so this object does not define them. @dynamic leaves respondsToSelector: answering NO, which is the truth,
// where a method that answered NO would be a name the port claims and does not carry.
//
// disconnected, testingModes and backingStoreIdentity are here for a second reason beyond 16.0:
// what each promises is a system rather than a setting. A domain is "disconnected from its
// extension" and there is no extension; a testing mode "alters the behavior of the system" and
// there is no system to alter; a backing store identity names "the backing store of the domain on
// the system" and there is none. Their registry rows answer absent, and the @dynamic is what
// makes that true at run time.
//
// hidden, replicated and supportsSyncingTrash are listed here for the other reason: the 16.0
// CATEGORY answers them, through the charon_ accessors above.
@dynamic hidden;
@dynamic disconnected;
@dynamic replicated;
@dynamic testingModes;
@dynamic supportsSyncingTrash;
@dynamic backingStoreIdentity;

- (id)initWithIdentifier:(NSString *)identifier
             displayName:(NSString *)displayName
pathRelativeToDocumentStorage:(NSString *)relative {
  self = [super init];
  if (self) {
    _charonIdentifier = [identifier copy];
    _charonDisplayName = [displayName copy];
    _charonRelative = [relative copy];
  }
  return self;
}
@end

// The 16.0 two-argument init lives in ITS OWN object, not in the 11.0 one. It was in the 11.0 piece at
// first and that is exactly what release-split refuses: an object whose symbols first appear in two
// releases. The generator's one-band-per-file assertion did not catch it - the tag was single per band -
// so the table has to be right as well as checked, and the check that would have caught it is release-split.

@implementation NSFileProviderDomain (Charon16)
- (id)initWithIdentifier:(NSString *)identifier displayName:(NSString *)displayName {
  return [self initWithIdentifier:identifier displayName:displayName
      pathRelativeToDocumentStorage:@""];
}

// The members the 16.0 header carries and this release lacks, answered through the class that owns the
// storage: this target gives a category no ivar of its own, so the state is the class's and these are the
// accessors the class publishes.
- (BOOL)userEnabled { return [self charon_userEnabled]; }
- (void)setUserEnabled:(BOOL)userEnabled {
  [self charon_setUserEnabled:userEnabled replicated:[self charon_replicated]
                      hidden:[self charon_hidden] supportsSyncingTrash:[self charon_supportsSyncingTrash]];
}
- (BOOL)replicated { return [self charon_replicated]; }
- (void)setReplicated:(BOOL)replicated {
  [self charon_setUserEnabled:[self charon_userEnabled] replicated:replicated
                      hidden:[self charon_hidden] supportsSyncingTrash:[self charon_supportsSyncingTrash]];
}
- (BOOL)hidden { return [self charon_hidden]; }
- (void)setHidden:(BOOL)hidden {
  [self charon_setUserEnabled:[self charon_userEnabled] replicated:[self charon_replicated]
                      hidden:hidden supportsSyncingTrash:[self charon_supportsSyncingTrash]];
}
- (BOOL)supportsSyncingTrash { return [self charon_supportsSyncingTrash]; }
- (void)setSupportsSyncingTrash:(BOOL)supportsSyncingTrash {
  [self charon_setUserEnabled:[self charon_userEnabled] replicated:[self charon_replicated]
                      hidden:[self charon_hidden] supportsSyncingTrash:supportsSyncingTrash];
}
@end

// NO CLASS IS EMITTED HERE, AND THAT IS THE POINT. NSFileProviderManager is defined by
// FileProvider/NSFileProviderManager.m, which is main s work and is not mine to touch. A second
// @implementation for one class is a duplicate class symbol at load - the nm sweep calls it "class defined
// twice" and the process dies before main ever runs - so the generator REFUSES to emit a class any object
// in the tree already defines, naming the file that has it, and this piece exists to hold the policy the
// manager needs without owning the class.
//
// The names below are CARRIED by that file and are never invoked by a differential: addDomain and
// removeDomain would ask this machine to mount a provider domain, and signalEnumerator would ask it to
// watch one. They are in this spec so the check that reads them has one place to read them from.
